"use client";

import React, { useState } from "react";
import { ShieldCheck } from "lucide-react";

export function CRMAccountHealthCard() {
  const [score, setScore] = useState(94);

  return (
    <div className="w-full max-w-sm bg-card/45 backdrop-blur-xl border border-border/50 p-5 rounded-2xl shadow-xl select-none font-sans text-foreground">
      <div className="flex items-center justify-between mb-4">
        <div className="flex items-center gap-1.5">
          <ShieldCheck className="w-4 h-4 text-emerald-400" />
          <span className="text-xs font-bold uppercase tracking-wider text-muted-foreground">Client Health Score</span>
        </div>
        <span className="text-[9px] uppercase font-bold text-emerald-400 bg-emerald-500/10 px-2 py-0.5 rounded border border-emerald-500/20">Excellent</span>
      </div>

      <div className="flex items-center justify-between bg-secondary/20 p-3.5 rounded-xl border border-white/[0.04]">
        <div>
          <span className="text-[10px] uppercase font-bold text-muted-foreground/60 leading-none">AeroLabs Core</span>
          <span className="block text-xs text-muted-foreground/80 mt-1">Enterprise Subscription Plan</span>
        </div>
        <span className="text-2xl font-black text-foreground">{score}</span>
      </div>
    </div>
  );
}
